#!/usr/bin/env node
/**
 * Protect Files - PreToolUse Hook for Edit|Write
 * Blocks hand edits to generated files, lockfiles and env files.
 * prisma/migrations/ is generated via `prisma migrate dev` and must never be
 * edited by hand (CLAUDE.md / ARCHITECTURE.md).
 *
 * Fails closed: if the hook input cannot be parsed, the edit is denied.
 * (The previous bash version depended on `jq`; without it, it silently allowed everything.)
 */

const path = require("path");

// Templates that document env vars are safe to edit.
const ENV_TEMPLATE = /^\.env\.(example|sample|template)$/i;

const RULES = [
  {
    id: "env-file",
    test: (p) => /^\.env(\..+)?$/i.test(path.basename(p)) && !ENV_TEMPLATE.test(path.basename(p)),
    reason: "env files hold secrets and are machine-local",
  },
  {
    id: "lockfile",
    test: (p) => path.basename(p) === "pnpm-lock.yaml",
    reason: "lockfile is generated by pnpm",
  },
  {
    id: "generated-dir",
    test: (p) => /(^|\/)(node_modules|\.next|\.turbo|dist)\//.test(p),
    reason: "generated/build output",
  },
  {
    id: "prisma-migration",
    test: (p) => /(^|\/)prisma\/migrations\//.test(p),
    reason: "migrations are generated with `prisma migrate dev`, never edited by hand",
  },
];

function check(filePath) {
  if (!filePath) return { blocked: false, rule: null };
  const normalized = filePath.split(path.sep).join("/");
  const rule = RULES.find((r) => r.test(normalized));
  return rule ? { blocked: true, rule } : { blocked: false, rule: null };
}

function deny(reason) {
  console.log(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason: reason,
      },
    }),
  );
}

async function main() {
  let input = "";
  for await (const chunk of process.stdin) input += chunk;

  let data;
  try {
    data = JSON.parse(input);
  } catch {
    return deny("[protect-files] could not parse hook input; denying edit (fail-closed)");
  }

  const filePath = data?.tool_input?.file_path;
  const result = check(filePath);
  if (result.blocked) {
    return deny(`[${result.rule.id}] Cannot edit ${filePath}: ${result.rule.reason}`);
  }
  console.log("{}");
}

if (require.main === module) {
  main();
} else {
  module.exports = { RULES, check };
}
